style.css:
@-moz-document domain("youtube.com") {
/* Background image for body and main container */
  body, ytd-app {
    background: url("https://i.imgur.com/VxU4aYO.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #f0f0f0 !important;
  }

  /* Semi-transparent containers */
  ytd-page-manager, ytd-watch-flexy, ytd-two-column-browse-results-renderer,
  ytd-rich-grid-renderer, ytd-masthead, #container.ytd-masthead {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  /* Text styling */
  yt-formatted-string, h1.title, #video-title, .style-scope {
    color: #e0e0e0 !important;
  }

  /* Video titles */
  a#video-title {
    color: #ffffff !important;
  }

  /* Links */
  a {
    color: #9dcfff !important;
  }

  a:hover {
    color: #ffffff !important;
  }

  /* Buttons */
  paper-button, yt-icon-button, button {
    background-color: #222 !important;
    color: #fff !important;
  }

  /* Scrollbar styling */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.3);
  }

  ::-webkit-scrollbar-thumb {
    background: #555;
    border-radius: 4px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #888;
  }
}
